import java.util.*;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

class CosmicCats {
    private final Set<String> cats = new HashSet<>(Arrays.asList("Whiskers", "Paws", "Claw"));

    public boolean isCat(String identifier) {
        return cats.contains(identifier);
    }

    public String displayCats() {
        return String.join(", ", cats);
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException {
        CosmicCats cosmicCats = new CosmicCats();

        ExecutorService executor = Executors.newFixedThreadPool(2);

        executor.execute(() -> System.out.println("Is Whiskers a Cat? " + cosmicCats.isCat("Whiskers")));
        executor.execute(() -> System.out.println("Cat identifiers: " + cosmicCats.displayCats()));

        executor.shutdown();
        executor.awaitTermination(1, TimeUnit.MINUTES);
    }
}

class CosmicCats {
  private final Set<String> catIdentifiers;

  public CosmicCats() {
    catIdentifiers = Set.of("Whiskers", "Paws", "Claw");
  }

  public boolean isCat(String identifier) {
    return catIdentifiers.contains(identifier);
  }

  public String displayCats() {
    return catIdentifiers.stream().collect(Collectors.joining(", ", "[", "]"));
  }
}

public class Main {
  public static void main(String[] args) throws InterruptedException, ExecutionException {
    CosmicCats cats = new CosmicCats();
    ExecutorService executor = Executors.newFixedThreadPool(2);
    executor.execute(() -> System.out.println(cats.displayCats()));
    executor.execute(() -> {
      System.out.println("Is Whiskers a cat? " + cats.isCat("Whiskers"));
      System.out.println("Is Mittens a cat? " + cats.isCat("Mittens"));
    });

    executor.shutdown();
    executor.awaitTermination(1, TimeUnit.MINUTES);
  }
}

import java.util.HashSet;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

class CosmicCats {
    private final Set<String> catIdentifiers;

    public CosmicCats() {
        catIdentifiers = new HashSet<>();
        catIdentifiers.add("Whiskers");
        catIdentifiers.add("Paws");
        catIdentifiers.add("Claw");
    }

    public boolean isCatIdentifier(String identifier) {
        return catIdentifiers.contains(identifier);
    }

    public String displayCatIdentifiers() {
        StringBuilder sb = new StringBuilder();
        sb.append("[");
        for (String identifier : catIdentifiers) {
            sb.append("\"");
            sb.append(identifier);
            sb.append("\", ");
        }
        if (sb.length() > 2) {
            sb.delete(sb.length() - 2, sb.length());
        }
        sb.append("]");
        return sb.toString();
    }

public static void main(String[] args) {
    CosmicCats cosmicCats = new CosmicCats();

    ExecutorService executorService = Executors.newFixedThreadPool(2);

    Runnable task1 = () -> System.out.println("Cat Identifiers: " + cosmicCats.displayCatIdentifiers());
    executorService.execute(task1);

    Runnable task2 = () -> {
        for (String identifier : new String[]{"Whiskers", "Mittens"}) {
            System.out.println(identifier + ": " + cosmicCats.isCatIdentifier(identifier));
        }
    };
    executorService.execute(task2);

    executorService.shutdown();
}
}

