import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;
import java.util.Random;

class ParcelMover {

    static class ParcelCount {
        int count;

        ParcelCount(int initialCount) {
            this.count = initialCount;
        }
    }

    static class Locker {
        private final ReentrantLock lock = new ReentrantLock();
        private ParcelCount parcels;

        Locker(int initialParcelCount) {
            this.parcels = new ParcelCount(initialParcelCount);
        }

        boolean moveParcels(Locker target, int quantity, long timeout, TimeUnit unit) throws NotEnoughItemsException {
            long nanosTimeout = unit.toNanos(timeout);
            long deadline = System.nanoTime() + nanosTimeout;
            Random random = new Random();
            while (System.nanoTime() < deadline) {
                if (lock.tryLock()) {
                    try {
                        if (target.lock.tryLock()) {
                            try {
                                if (parcels.count >= quantity) {
                                    parcels.count -= quantity;
                                    target.parcels.count += quantity;
                                    return true;
                                } else {
                                    throw new NotEnoughItemsException("Not enough parcels in the source locker.");
                                }
                            } finally {
                                target.lock.unlock();
                            }
                        } else {
                            // Pause before retrying
                            long fixedDelay = 100;
                            long randomDelay = random.nextInt(50);
                            try {
                                Thread.sleep(fixedDelay + randomDelay);
                            } catch (InterruptedException e) {
                                return false;
                            }
