import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;

class ParcelMover {
  static class Locker {
    private final ReentrantLock lock = new ReentrantLock();
    private int parcelCount;

    Locker(int initialParcelCount) {
      this.parcelCount = initialParcelCount;
    }

    void addParcels(int count) {
      lock.lock();
      try {
        parcelCount += count;
      } finally {
        lock.unlock();
      }
    }

    boolean removeParcels(int count) {
      lock.lock();
      try {
        if (parcelCount >= count) {
          parcelCount -= count;
          return true;
        }
      } finally {
        lock.unlock();
      }
      return false;
    }

    int getParcelCount() {
      lock.lock();
      try {
        return parcelCount;
      } finally {
        lock.unlock();
      }
    }
  }

  static class NotEnoughItemsException extends Exception {}

  static boolean move(Locker source, Locker target, int quantity, long timeout, TimeUnit unit) throws NotEnoughItemsException {
    long startTime = System.nanoTime();
    long endTime = startTime + unit.toNanos(timeout);

    while (System.nanoTime() < endTime) {
      if (source.lock.tryLock()) {
        try {
          if (target.lock.tryLock()) {
            try {
              if (source.removeParcels(quantity)) {
                target.addParcels(quantity);
                return true;
              } else {
                throw new NotEnoughItemsException();
              }
            } finally {
              target.lock.unlock();
            }
          }
        } finally {
          source.lock.unlock();
        }
      }

      try {
        Thread.sleep((long) (Math.random() * 100));
      } catch (InterruptedException e) {}
    }
    return false;
  }

  public static void main(String[] args) throws InterruptedException {
    Locker source = new Locker(10);
    Locker target = new Locker(5);

    Thread moverThread = new Thread(() -> {
      try {
        boolean success = move(source, target, 3, 2, TimeUnit.SECONDS);
        System.out.println("Move successful: " + success);
      } catch (NotEnoughItemsException e) {
        System.err.println("Not enough items in the source locker.");
      }
    });

    moverThread.start();
    moverThread.join();
  }
}

import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;
import java.util.Random;

public class ParcelMover {

    static class ParcelCount {
        private int count;
        public ParcelCount(int initialCount) {
            this.count = initialCount;
        }
        public synchronized void add(int amount) {
            count += amount;
        }
        public synchronized void subtract(int amount) throws NotEnoughItemsException {
            if (count < amount) {
                throw new NotEnoughItemsException("Not enough items in the locker.");
            }
            count -= amount;
        }
        public synchronized int getCount() {
            return count;
        }
    }

    static class Locker {
        private ParcelCount parcels;
        private ReentrantLock lock = new ReentrantLock();
        public Locker(int initialParcelCount) {
            this.parcels = new ParcelCount(initialParcelCount);
        }
        public boolean moveParcels(Locker target, int quantity, long timeout, TimeUnit unit) throws NotEnoughItemsException {
            long startTime = System.nanoTime();
            long nanosTimeout = unit.toNanos(timeout);

            while (System.nanoTime() - startTime < nanosTimeout) {
                if (lock.tryLock()) {
                    try {
                        if (target.lock.tryLock()) {
                            try {
                                parcels.subtract(quantity);
                                target.parcels.add(quantity);
                                return true;
                            } finally {
                                target.lock.unlock();
                            }
                        } else {
                            pauseRandomly();
                        }
                    } finally {
                        lock.unlock();
                    }
                } else {
                    pauseRandomly();
                }
            }
            return false;
        }

        private void pauseRandomly() {
            try {
                Thread.sleep(getFixedDelay() + getRandomDelay());
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        private long getFixedDelay() {
            return 10; // milliseconds
        }

        private long getRandomDelay() {
            Random random = new Random();
            return random.nextInt(50); // milliseconds
        }
    }

    static class NotEnoughItemsException extends Exception {
        public NotEnoughItemsException(String message) {
            super(message);
        }
    }

    public static void main(String[] args) throws InterruptedException {

        Locker sourceLocker = new Locker(10);
        Locker targetLocker = new Locker(5);

        Thread moverThread = new Thread(() -> {
            try {
                boolean success = sourceLocker.moveParcels(targetLocker, 3, 2, TimeUnit.SECONDS);
                System.out.println("Move successful: " + success);
            } catch (NotEnoughItemsException e) {
                System.err.println("Error: " + e.getMessage());
            }
        });

        moverThread.start();
        moverThread.join();
    }
}

