class InsufficientElementsException extends Exception {}

public class DeadlockAvoidance {
    public static boolean swap(Container origin, Container target, int count, long timeout, TimeUnit unit) throws InsufficientElementsException {
        long startTime = System.nanoTime();
        while (unit.toNanos(timeout) > System.nanoTime() - startTime) {
            if (origin.lock.tryLock()) {
                try {
                    if (target.lock.tryLock()) {
                        try {
                            if (origin.elements.count >= count) {
                                origin.elements.count -= count;
                                target.elements.count += count;
                                return true;
                            } else {
                                throw new InsufficientElementsException();
                            }
                        } finally {
                            target.lock.unlock();
                        }
                    } else {
                        Thread.sleep(getFixedDelay() + (long) (Math.random() * getRandomDelay()));
                    }
                } finally {
                    origin.lock.unlock();
                }
            } else {
                Thread.sleep(getFixedDelay() + (long) (Math.random() * getRandomDelay()));
            }
        }
        return false;
    }

    private static long getFixedDelay() {
        return 10;
    }

    private static long getRandomDelay() {
        return 50;
    }

