  private ExecutorService executor = Executors.newFixedThreadPool(2);

  public List<Talisman> weaveTalismansSequentially(List<Talisman> talismans) throws InterruptedException {
    List<Talisman> enchantedTalismans = new ArrayList<>();
    for (Talisman talisman : talismans) {
      enchantedTalismans.add(enchant(talisman));
    }
    return enchantedTalismans;
  }

  public List<Talisman> weaveTalismansConcurrently(List<Talisman> talismans) throws InterruptedException, ExecutionException {
    List<Talisman> enchantedTalismans = new ArrayList<>();
    for (Talisman talisman : talismans) {
      executor.submit(() -> enchantedTalismans.add(enchant(talisman)));
    }

    executor.shutdown();
    executor.awaitTermination(1, TimeUnit.HOURS);
    return enchantedTalismans;
  }

  private Talisman enchant(Talisman talisman) {
    int power = talisman.getEnchantmentPower();
    // Simulate enchantment process
