        return result;
    }

    public List<RuneNode<T>> getChildren() {
        return children;
    }
}

class Spellcaster {
    private final ExecutorService executor = Executors.newFixedThreadPool(2);

    public <T> List<T> castSequentially(List<Charm<T>> charms) {
        List<T> results = new ArrayList<>();
        for (Charm<T> charm : charms) {
            results.add(charm.invoke());
        }
        return results;
    }

    public <T> List<T> castConcurrently(List<Charm<T>> charms) throws InterruptedException, ExecutionException {
        List<Future<T>> futures = new ArrayList<>();
        for (Charm<T> charm : charms) {
            futures.add(executor.submit(() -> charm.invoke()));
        }
        List<T> results = new ArrayList<>();
        for (Future<T> future : futures) {
            results.add(future.get());
        }
        return results;
    }

    public <T> List<T> castSequentiallyRecursive(RuneNode<T> root) {
        List<T> results = new ArrayList<>();
        results.add(root.compute());
        for (RuneNode<T> child : root.getChildren()) {
            results.addAll(castSequentiallyRecursive(child));
        }
        return results;
    }

    public <T> List<T> castConcurrentlyRecursive(RuneNode<T> root) throws InterruptedException, ExecutionException {
