void processInParallel(Executor exec, List<Element> elements) {
CountDownLatch latch = new CountDownLatch(elements.size());
for (final Element e : elements) {
exec.execute(() -> {
process(e);
latch.countDown();
});
}
try {
latch.await();
} catch (InterruptedException ie) {
Thread.currentThread().interrupt();
}
}

