class Hoard {
  private int gems;

  public Hoard(int initialGems) {
    this.gems = initialGems;
  }

  public synchronized void withdraw(int amount) throws InsufficientGemsException {
    if (gems < amount) {
      throw new InsufficientGemsException("Insufficient gems in hoard.");
    }
    gems -= amount;
  }

  public synchronized void deposit(int amount) {
    gems += amount;
  }

  public int getGems() {
    return gems;
  }

  @Override
  public int hashCode() {
    return System.identityHashCode(this);
  }
}

interface GemAmount {
  int getAmount();
}

class InsufficientGemsException extends Exception {
  public InsufficientGemsException(String message) {
    super(message);
  }
}

class TransferRitual implements Runnable {
  private final Hoard sourceHoard;
  private final Hoard destinationHoard;
  private final GemAmount amount;

  public TransferRitual(Hoard sourceHoard, Hoard destinationHoard, GemAmount amount) {
    this.sourceHoard = sourceHoard;
    this.destinationHoard = destinationHoard;
    this.amount = amount;
  }

  @Override
  public void run() {
    try {
      if (sourceHoard.hashCode() < destinationHoard.hashCode()) {
        synchronized (sourceHoard) {
          synchronized (destinationHoard) {
            transferGems();
          }
        }
      } else if (sourceHoard.hashCode() > destinationHoard.hashCode()) {
        synchronized (destinationHoard) {
          synchronized (sourceHoard) {
            transferGems();
          }
        }
      } else {
        Object tieBreaker = new Object();
        synchronized (tieBreaker) {
          synchronized (sourceHoard) {
            synchronized (destinationHoard) {
              transferGems();
            }
          }
        }
      }
    } catch (InsufficientGemsException e) {
      System.err.println("Transfer failed: " + e.getMessage());
    }
  }

  private void transferGems() throws InsufficientGemsException {
    sourceHoard.withdraw(amount.getAmount());
    destinationHoard.deposit(amount.getAmount());
    System.out.println("Transferred " + amount.getAmount() + " gems from hoard "
        + sourceHoard.hashCode() + " to hoard " + destinationHoard.hashCode());
  }
}

class GemTransfer {
  public static void main(String[] args) {
    Hoard hoard1 = new Hoard(100);
    Hoard hoard2 = new Hoard(50);

    Thread thread1 = new Thread(new TransferRitual(hoard1, hoard2, () -> 20));
    Thread thread2 = new Thread(new TransferRitual(hoard2, hoard1, () -> 30));

    thread1.start();
    thread2.start();

    try {
      thread1.join();
      thread2.join();
    } catch (InterruptedException e) {
