class TransferRite implements Runnable {
    private final VaultNode source;
    private final VaultNode destination;
    private final CrystalAmount amount;
    private final Object lock1 = new Object();
    private final Object lock2 = new Object();

    public TransferRite(VaultNode source, VaultNode destination, CrystalAmount amount) {
        this.source = source;
        this.destination = destination;
        this.amount = amount;
    }

    @Override
    public void run() {
        try {
            int sourceHashCode = source.getId();
            int destHashCode = destination.getId();

            Object primaryLock = sourceHashCode < destHashCode ? lock1 : lock2;
            Object secondaryLock = sourceHashCode < destHashCode ? lock2 : lock1;

            synchronized (primaryLock) {
                synchronized (secondaryLock) {
                    if (source.getCrystals() >= amount.getAmount()) {
                        source.withdraw(amount.getAmount());
                        destination.deposit(amount.getAmount());
                        System.out.println("Transfer successful from node " + source.getId() + " to node " + destination.getId()
                                + ": " + amount.getAmount() + " crystals transferred.");
