class TransferHelper {
    private final Object tieBreakLock = new Object();

    public void transfer(VaultNode from, VaultNode to, CrystalAmount amount) throws InsufficientCrystalsException {
        int fromHashCode = from.getId();
        int toHashCode = to.getId();

        if (fromHashCode < toHashCode) {
            synchronized (from) {
                synchronized (to) {
                    validateTransfer(from, to, amount);
                    from.setCrystals(from.getCrystals() - amount.getAmount());
                    to.setCrystals(to.getCrystals() + amount.getAmount());
                }
            }
        } else if (fromHashCode > toHashCode) {
            synchronized (to) {
                synchronized (from) {
                    validateTransfer(from, to, amount);
                    from.setCrystals(from.getCrystals() - amount.getAmount());
                    to.setCrystals(to.getCrystals() + amount.getAmount());
                }
