class ChronomanticDragonTracker {
    private Constellation<String, MutableOrb> constellation;

    ChronomanticDragonTracker(Constellation<String, MutableOrb> initialConstellation) {
        this.constellation = deepClone(initialConstellation);
    }

    synchronized Constellation<String, MutableOrb> getConstellations() {
        return deepClone(constellation);
    }

    synchronized MutableOrb getOrb(String sigil) {
        MutableOrb orb = constellation.get(sigil);
        if (orb != null) {
            return new MutableOrb(orb.shimmerX, orb.shimmerY);
        }
        return null;
    }

    synchronized void setOrb(String sigil, int shimmerX, int shimmerY) {
        if (!constellation.containsKey(sigil)) {
            throw new IllegalArgumentException("Sigil not found: " + sigil);
