class ChronomanticDragonTracker implements Constellation<String, MutableOrb> {
    private final Map<String, MutableOrb> constellation = new HashMap<>();

    ChronomanticDragonTracker(Constellation<String, MutableOrb> initial) {
        constellation.putAll(deepClone(initial));
    }

    private static <K, V> Map<K, V> deepClone(Constellation<K, V> source) {
        Map<K, V> clone = new HashMap<>();
        for (Map.Entry<K, V> entry : source.entrySet()) {
            clone.put(entry.getKey(), ((MutableOrb) entry.getValue()).clone());
        }
        return clone;
