class CelestialHourglass implements Runnable {
  private boolean activated;
  private long dawnTime;
  private long duskTime;

  @Override
  public synchronized void run() {
    long currentChronon = System.nanoTime();
    if (!activated) {
      activated = true;
      dawnTime = currentChronon;
    } else {
      duskTime = currentChronon;
    }
  }

  public synchronized void reset() {
    activated = false;
  }

  public synchronized long getFlow() {
    return duskTime - dawnTime;
  }
}

public class Main {
  public static void main(String[] args) throws InterruptedException {
    CelestialHourglass hourglass = new CelestialHourglass();
    Thread thread1 = new Thread(hourglass);
    Thread thread2 = new Thread(hourglass);

    thread1.start();
    thread2.start();

    thread1.join();
