    private EnchantedCAS dustLevel = new EnchantedCAS(0);

    public int getDustLevel() {
        return dustLevel.get();
    }

    public void sprinkle() {
        while (true) {
            int expected = dustLevel.get();
            if (dustLevel.compareAndSwap(expected, expected + 1)) {
                break;
            }
        }
    }
}

