class DollarAmount {
  private final int amount;
  public DollarAmount(int amount) { this.amount = amount; }
  public int getAmount() { return amount; }
}

class Account {
  private final ReentrantLock lock = new ReentrantLock();
  private DollarAmount balance;

  public Account(DollarAmount initialBalance) {
    this.balance = initialBalance;
  }

  public boolean transfer(Account dest, DollarAmount amount, long timeout, TimeUnit unit) throws InsufficientFundsException {
    long startTime = System.nanoTime();
    while (true) {
      if (lock.tryLock()) {
        try {
          if (dest.lock.tryLock()) {
            try {
              if (balance.getAmount() >= amount.getAmount()) {
                balance = new DollarAmount(balance.getAmount() - amount.getAmount());
                dest.balance = new DollarAmount(dest.balance.getAmount() + amount.getAmount());
                return true;
              } else {
                throw new InsufficientFundsException();
              }
            } finally {
              dest.lock.unlock();
            }
          } else {
            long elapsedTime = TimeUnit.NANOSECONDS.convert(System.nanoTime() - startTime, TimeUnit.NANOSECONDS);
            if (elapsedTime >= unit.toNanos(timeout)) {
              return false;
            } else {
              int delay = fixedDelay(10) + randomDelay(2);
              try { Thread.sleep(delay); } catch (InterruptedException e) {} 
            }
          }
        } finally {
          lock.unlock();
        }
      } else {
        long elapsedTime = TimeUnit.NANOSECONDS.convert(System.nanoTime() - startTime, TimeUnit.NANOSECONDS);
        if (elapsedTime >= unit.toNanos(timeout)) {
          return false;
        } else {
          int delay = fixedDelay(10) + randomDelay(2);
          try { Thread.sleep(delay); } catch (InterruptedException e) {} 
        }
      }
    }
  }

  private int fixedDelay(int baseDelay) { return baseDelay; }

  private int randomDelay(int range) {
    return (int) (Math.random() * range);
  }
}

