    Thread thread1 = new Thread(timer);
    Thread thread2 = new Thread(timer);

    thread1.start();
    Thread.sleep(10);
    thread2.start();

    thread1.join();
    thread2.join();

    System.out.println(timer.getTime());
    timer.clear();
  }
}

