import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;

public class TreiberStack {
    static class Node {
        int item;
        AtomicReference<Node> next;

        Node(int item) {
            this.item = item;
            this.next = new AtomicReference<>(null);
        }
    }

    private AtomicReference<Node> top = new AtomicReference<>(null);

    public void push(int item) {
        Node newNode = new Node(item);
        while (true) {
            Node currentTop = top.get();
            newNode.next.set(currentTop);
            if (top.compareAndSet(currentTop, newNode)) {
                break;
            }
        }
    }

    public Integer pop() {
        while (true) {
            Node currentTop = top.get();
            if (currentTop == null) {
                return null;
            }
            Node newTop = currentTop.next.get();
            if (top.compareAndSet(currentTop, newTop)) {
                return currentTop.item;
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        TreiberStack stack = new TreiberStack();
        ExecutorService executorService = Executors.newFixedThreadPool(3);

        for (int i = 0; i < 3; i++) {
            executorService.execute(() -> {
                for (int j = 0; j < 5; j++) {
                    stack.push(j);
                    System.out.println("Pushed: " + j);
                }

                for (int j = 0; j < 5; j++) {
                    Integer poppedItem = stack.pop();
                    System.out.println("Popped: " + poppedItem);
                }
            });
        }

        executorService.shutdown();
        executorService.awaitTermination(1, TimeUnit.HOURS);
        System.out.println("Stack operations completed.");
    }
}

