import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;

public class TreiberStack {

    private static class Node {
        int item;
        AtomicReference<Node> next;

        Node(int item, Node next) {
            this.item = item;
            this.next = new AtomicReference<>(next);
        }
    }

    private final AtomicReference<Node> top = new AtomicReference<>(null);

    public void push(int item) {
        Node newNode = new Node(item, top.get());
        while (!top.compareAndSet(newNode.next.get(), newNode)) {}
    }

    public Integer pop() {
        Node currentTop = top.get();
        if (currentTop == null) {
            return null;
        }
        while (!top.compareAndSet(currentTop, currentTop.next.get())) {}
        return currentTop.item;
    }

    public static void main(String[] args) throws InterruptedException {
