                }
                for (int j = 0; j < 5; j++) {
                    Integer popped = stack.pop();
                    System.out.println("Pop: " + popped);
                }
            });
        }

        executor.shutdown();
        executor.awaitTermination(1, TimeUnit.MINUTES);
        System.out.println("All threads completed.");
    }
