import java.util.List;
import java.util.ArrayList;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

interface Element {
    int process();
}

class Node implements Element {
    private final List<Node> children;
    private int value;

    public Node(int value) {
        this.value = value;
        this.children = new ArrayList<>();
    }

    public void addChild(Node child) {
        children.add(child);
    }

    @Override
    public int process() {
        int result = value;
        for (Node child : children) {
            result += child.process();
        }
        return result;
    }

    public List<Node> getChildren() {
        return children;
    }
}

class Processor {
    private final ExecutorService executor;

    public Processor() {
        executor = Executors.newFixedThreadPool(2);
    }

    public int processSequentially(List<Element> elements) {
        int result = 0;
        for (Element element : elements) {
            result += element.process();
        }
        return result;
    }

    public int processParallel(List<Element> elements) throws InterruptedException {
        List<java.util.concurrent.Callable<Integer>> tasks = new ArrayList<>();
        for (Element element : elements) {
            tasks.add(() -> element.process());
        }
        return executor.invokeAll(tasks).stream()
                .mapToInt(future -> {
                    try {
                        return future.get();
                    } catch (Exception e) {
                        throw new RuntimeException(e);
                    }
                })
                .sum();
    }

    public int processSequentiallyRecursive(Node node) {
        int result = node.process();
        for (Node child : node.getChildren()) {
            result += processSequentiallyRecursive(child);
        }
        return result;
    }

    public int processParallelRecursive(Node node) throws InterruptedException {
        List<java.util.concurrent.Callable<Integer>> tasks = new ArrayList<>();
        for (Node child : node.getChildren()) {
            tasks.add(() -> processParallelRecursive(child));
        }
        int result = node.process();
        result += executor.invokeAll(tasks).stream()
                .mapToInt(future -> {
                    try {
                        return future.get();
                    } catch (Exception e) {
                        throw new RuntimeException(e);
                    }
                })
                .sum();
        return result;

    }

    public void shutdown() {
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }
    }
}

