  private final ExecutorService executor = Executors.newFixedThreadPool(2);

  public <T extends Element> List<Integer> processSequentially(List<T> elements) {
    List<Integer> results = new ArrayList<>();
    for (T element : elements) {
      results.add(element.process());
    }
    return results;
  }

  public <T extends Element> List<Integer> processParallel(List<T> elements) throws InterruptedException {
    List<Integer> results = new ArrayList<>();
    for (T element : elements) {
      executor.submit(() -> results.add(element.process()));
    }
    executor.shutdown();
    executor.awaitTermination(1, TimeUnit.MINUTES);
    return results;
  }

  public <T extends Element> int processSequentiallyRecursive(Node root) {
    int sum = root.process();
    for (Node child : root.getChildren()) {
      sum += processSequentiallyRecursive(child);
    }
    return sum;
  }

  public <T extends Element> int processParallelRecursive(Node root) throws InterruptedException {
    List<Integer> results = new ArrayList<>();
    executor.submit(() -> results.add(root.process()));

    for (Node child : root.getChildren()) {
