        this.value = value;
        this.children = new ArrayList<>();
    }

    public void addChild(Node child) {
        children.add(child);
    }

    @Override
    public int getValue() {
        return value;
    }

    public List<Node> getChildren() {
        return children;
    }
}

class Processor {
    private final ExecutorService executor = Executors.newFixedThreadPool(2);

    public List<Integer> processSequentially(List<Element> elements) {
        List<Integer> results = new ArrayList<>();
        for (Element element : elements) {
            results.add(element.getValue());
        }
        return results;
    }

    public List<Integer> processParallel(List<Element> elements) throws InterruptedException, ExecutionException {
        List<Callable<Integer>> tasks = new ArrayList<>();
        for (Element element : elements) {
            tasks.add(() -> element.getValue());
        }
        List<Future<Integer>> futures = executor.invokeAll(tasks);
        List<Integer> results = new ArrayList<>();
        for (Future<Integer> future : futures) {
            results.add(future.get());
        }
        return results;
    }

    public List<Integer> processSequentiallyRecursive(Node node) {
        List<Integer> results = new ArrayList<>();
        results.add(node.getValue());
        for (Node child : node.getChildren()) {
            results.addAll(processSequentiallyRecursive(child));
        }
        return results;
    }

    public List<Integer> processParallelRecursive(Node node) throws InterruptedException, ExecutionException {
        List<Callable<List<Integer>>> tasks = new ArrayList<>();
        tasks.add(() -> {
            List<Integer> results = new ArrayList<>();
            results.add(node.getValue());
            for (Node child : node.getChildren()) {
                results.addAll(processParallelRecursive(child).get());
            }
            return results;
        });

        List<Future<List<Integer>>> futures = executor.invokeAll(tasks);
        List<Integer> finalResults = new ArrayList<>();
        for (Future<List<Integer>> future : futures) {
            finalResults.addAll(future.get());
        }
        return finalResults;
    }

}



