private final List<Node<String>> children;
public MyNode(String name, List<Node<String>> children) {
this.name = name;
this.children = children != null ? children : Collections.emptyList();
}
public String compute() {
return name;
}
public List<Node<String>> getChildren() { return children; }
}

public static void main(String[] args) throws InterruptedException {
LLMC instance = new LLMC() {
public void process(Element e) {
// Minimal processing
}
};

