import java.util.Map;
import java.util.concurrent.locks.ReentrantReadWriteLock;

class ReadWriteMap<K, V> {
    private final Map<K, V> map;
    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();

    public ReadWriteMap(Map<K, V> map) {
        this.map = map;
    }

    public V get(Object key) {
        lock.readLock().lock();
        try {
            return map.get(key);
        } finally {
            lock.readLock().unlock();
        }
    }

    public int size() {
        lock.readLock().lock();
        try {
            return map.size();
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean isEmpty() {
        lock.readLock().lock();
        try {
            return map.isEmpty();
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean containsKey(Object key) {
        lock.readLock().lock();
        try {
            return map.containsKey(key);
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean containsValue(Object value) {
        lock.readLock().lock();
        try {
            return map.containsValue(value);
        } finally {
            lock.readLock().unlock();
        }
    }

    public V put(K key, V value) {
        lock.writeLock().lock();
        try {
            return map.put(key, value);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public V remove(Object key) {
        lock.writeLock().lock();
        try {
            return map.remove(key);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void putAll(Map<? extends K, ? extends V> m) {
        lock.writeLock().lock();
        try {
            map.putAll(m);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void clear() {
        lock.writeLock().lock();
        try {
            map.clear();
        } finally {
            lock.writeLock().unlock();
        }
    }
}

class Task implements Runnable {
    private final ReadWriteMap<Integer, String> map;

    public Task(ReadWriteMap<Integer, String> map) {
        this.map = map;
    }

    @Override
    public void run() {
        for (int i = 0; i < 2; i++) {
            map.put(i, "Value" + i);
            System.out.println("Thread: " + Thread.currentThread().getName() + ", Put key: " + i);
        }
    }
}

public class Main {
    public static void main(String[] args) {
        ReadWriteMap<Integer, String> readWriteMap = new ReadWriteMap<>(new java.util.HashMap<>());
        Thread thread1 = new Thread(new Task(readWriteMap));
        thread1.start();

        Thread thread2 = new Thread(new Task(readWriteMap));
        thread2.start();

        try {
            thread1.join();
            thread2.join();
        } catch (InterruptedException e) {
            System.err.println("Threads interrupted: " + e.getMessage());
        }

        System.out.println("Map size: " + readWriteMap.size());
    }
}```

