import java.util.HashMap;
import java.util.Map;

public class SimpleReadWriteMap<K, V> {
private final Map<K, V> map = new HashMap<>();

public synchronized V put(K key, V value) {
return map.put(key, value);
}

public synchronized V get(Object key) {
return map.get(key);
}

public synchronized int size() {
return map.size();
}

public static void main(String[] args) throws InterruptedException {
final SimpleReadWriteMap<String, String> rwMap = new SimpleReadWriteMap<>();

Thread writer = new Thread(new Runnable() {
public void run() {
for (int i = 0; i < 3; i++) {
rwMap.put("key" + i, "value" + i);
System.out.println("Writer wrote: key" + i);
}
}
});

Thread reader1 = new Thread(new Runnable() {
public void run() {
for (int i = 0; i < 3; i++) {
String val = rwMap.get("key" + i);
if (val != null) {
System.out.println("Reader1 read: " + val);
}
}
}
});

Thread reader2 = new Thread(new Runnable() {
public void run() {
for (int i = 0; i < 3; i++) {
String val = rwMap.get("key" + i);
if (val != null) {
System.out.println("Reader2 read: " + val);
}
}
}
});

writer.start();
reader1.start();
reader2.start();

writer.join();
reader1.join();
reader2.join();

System.out.println("Final size: " + rwMap.size());
}
}

